{
    int ret;

    ret = next active();
    LedgerAllocationRule curLedgerAllocationRule = this.cursor();
    this.object(fieldNum(LedgerAllocationRule, AVAAutomaticHeadcountUpdate)).enabled(curLedgerAllocationRule.AllocationMethod == LedgerAllocationMethod::FixedWeight);
    this.object(fieldNum(LedgerAllocationRule, AVADestinationMainAccount)).enabled(curLedgerAllocationRule.AllocationMethod == LedgerAllocationMethod::FixedWeight);
    //                                                                                && curLedgerAllocationRule.AVAAutomaticHeadcountUpdate);
    //this.object(fieldNum(LedgerAllocationRule, AVADestinationMainAccount)).mandatory(curLedgerAllocationRule.AllocationMethod == LedgerAllocationMethod::FixedWeight);
    //                                                                                   && curLedgerAllocationRule.AVAAutomaticHeadcountUpdate);

    this.object(fieldNum(LedgerAllocationRule, AVADestinationAccountNum)).enabled(curLedgerAllocationRule.AllocationMethod == LedgerAllocationMethod::Basis);
    this.object(fieldNum(LedgerAllocationRule, AVADestinationToLedgerDim)).enabled(curLedgerAllocationRule.AllocationMethod == LedgerAllocationMethod::Basis);
    this.object(fieldNum(LedgerAllocationRule, AVADestinationDimAttributeName)).enabled(curLedgerAllocationRule.AllocationMethod == LedgerAllocationMethod::Basis);
    this.object(fieldNum(LedgerAllocationRule, AVADestinationFromDimensionValue)).enabled(curLedgerAllocationRule.AllocationMethod == LedgerAllocationMethod::Basis);
    this.object(fieldNum(LedgerAllocationRule, AVADestinationToDimensionValue)).enabled(curLedgerAllocationRule.AllocationMethod == LedgerAllocationMethod::Basis);

    return ret;
}
